const typographyCss=`:root{--tv-font-small:clamp(14px,.92vw,18px);--tv-font-body:clamp(18px,1.15vw,22px);--tv-font-heading:clamp(24px,1.8vw,36px);--tv-font-metric:clamp(34px,3.3vw,60px);font-family:"Pretendard","Noto Sans KR",system-ui,sans-serif}html,body,button{font-family:inherit}.content{font-size:var(--tv-font-body);line-height:1.45}.scene-head h1,.board:has(.executive-overview) .scene-head h1{font-size:var(--tv-font-heading)}.content :is(h2,h3,.overview-title,.overview-cleaning h2,.overview-agenda h2,.overview-trend h2){font-size:var(--tv-font-heading)!important;line-height:1.3}.content :is(small,.roadmap-legend,.status-cell,.deadline-row,.undated,.mini-milestone,.strategy-person,.strategy-goal p,.overview-cleaning-total,.overview-cleaning header small,.overview-agenda header small,.overview-trend-chart small,.overview-trend-chart b){font-size:var(--tv-font-small)!important;line-height:1.35}.content :is(.card strong,.health-card strong,.revenue-card strong,.strategy-goal strong,.review-metric strong){font-size:var(--tv-font-metric)!important;font-variant-numeric:tabular-nums}.content .empty{font-size:var(--tv-font-body)}.progress,.content progress{border-radius:999px}`;

